                    'priority': str(record.get('Prioridad', 'Medium')),
                    'created': record['Creado el'].strftime('%Y-%m-%d %H:%M') if pd.notna(record['Creado el']) else '',
                    'assigned': str(record.get('Asignada a', ''))
                }
