    const issueTypes = {};
    data.forEach(item => {
        issueTypes[item.issue] = (issueTypes[item.issue] || 0) + 1;
    });

    const topIssues = Object.entries(issueTypes)
        .sort(([,a], [,b]) => b - a)
        .slice(0, 5);

    const topIssuesContainer = document.getElementById('topIssuesContainer');
    if (topIssuesContainer) {
